class Warrant{final String code,underlying,direction;final double strike,ratio,delta,leverage,bid,ask,volume;final DateTime expiry;Warrant({required this.code,required this.underlying,required this.direction,required this.strike,required this.expiry,required this.ratio,required this.delta,required this.leverage,required this.bid,required this.ask,required this.volume});double get spreadPct{final m=(bid+ask)/2;return m<=0?999:(ask-bid)/m*100;}int get daysToExpiry=>expiry.difference(DateTime.now()).inDays;factory Warrant.fromCsv(List<String> r)=>Warrant(code:r[0],underlying:r[1].toUpperCase(),direction:r[2].toUpperCase(),strike:double.tryParse(r[3])??0,expiry:DateTime.tryParse(r[4])??DateTime(2099),ratio:double.tryParse(r[5])??0,delta:double.tryParse(r[6])??0,leverage:double.tryParse(r[7])??0,bid:double.tryParse(r[8])??0,ask:double.tryParse(r[9])??0,volume:double.tryParse(r[10])??0);}
